PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "kysely_migration" ("name" varchar(255) not null primary key, "timestamp" varchar(255) not null);
CREATE TABLE IF NOT EXISTS "kysely_migration_lock" ("id" varchar(255) not null primary key, "is_locked" integer default 0 not null);
CREATE TABLE IF NOT EXISTS "revisions" ("id" text primary key, "page_id" text not null references "pages" ("id") on delete cascade, "content" text not null, "created_at" text not null, "kind" text default 'published' not null, "created_by" text, "created_via" text);
CREATE TABLE IF NOT EXISTS "settings" ("key" text primary key, "value" text not null, "updated_by" text);
CREATE TABLE IF NOT EXISTS "jobs" ("id" text primary key, "kind" text not null, "payload" text not null, "status" text not null, "error" text, "attempts" integer default 0 not null, "created_at" text not null, "finished_at" text, "result" text, "run_at" text, "log" text, "created_by" text);
CREATE TABLE IF NOT EXISTS "pages" ("id" text primary key, "parent_id" text references "pages" ("id"), "slug" text not null, "position" integer not null, "draft" text not null, "published_revision_id" text, "created_at" text not null, "updated_at" text not null, "deleted_at" text, "template" text, "kind" text default 'page' not null, "listing" text, "publish_at" text, "updated_by" text);
CREATE TABLE IF NOT EXISTS "redirects" ("id" text primary key, "source_path" text not null unique, "target_page_id" text references "pages" ("id") on delete cascade, "target_url" text, "status" integer not null, "page_id" text references "pages" ("id") on delete set null, "created_at" text not null);
CREATE TABLE IF NOT EXISTS "media" ("id" text primary key, "filename" text not null, "type" text not null, "ext" text not null, "size" integer not null, "width" integer, "height" integer, "alt" text default '' not null, "caption" text default '' not null, "credit" text default '' not null, "variants" text default '[]' not null, "variants_size" integer default 0 not null, "status" text not null, "created_at" text not null, "updated_at" text not null, "deleted_at" text, "decorative" integer default 0 not null, "replaced_at" text, "previous" text, "created_by" text);
CREATE TABLE IF NOT EXISTS "media_usage" ("media_id" text not null references "media" ("id") on delete cascade, "owner" text not null, constraint "media_usage_pk" primary key ("media_id", "owner"));
CREATE TABLE IF NOT EXISTS "users" ("id" text primary key, "username" text not null unique, "display_name" text not null, "role" text not null, "password_hash" text not null, "must_change_password" integer default 0 not null, "totp_secret" text, "totp_last_step" integer, "totp_enrolled_at" text, "preferences" text default '{"language":"en"}' not null, "disabled_at" text, "last_sign_in_at" text, "created_at" text not null, "created_by" text, "mcp_enabled" integer default 0 not null, "kind" text default 'person' not null);
CREATE TABLE IF NOT EXISTS "sessions" ("id" text primary key, "token_hash" text not null unique, "user_id" text not null references "users" ("id") on delete cascade, "stage" text not null, "created_at" text not null, "last_seen_at" text not null, "ip" text default '' not null, "user_agent" text default '' not null);
CREATE TABLE IF NOT EXISTS "tokens" ("id" text primary key, "token_hash" text not null unique, "kind" text not null, "role" text, "user_id" text references "users" ("id") on delete cascade, "note" text default '' not null, "created_by" text, "created_at" text not null, "expires_at" text not null, "used_at" text);
CREATE TABLE IF NOT EXISTS "recovery_codes" ("user_id" text not null references "users" ("id") on delete cascade, "code_hash" text not null, "used_at" text, constraint "recovery_codes_pk" primary key ("user_id", "code_hash"));
CREATE TABLE IF NOT EXISTS "audit_log" ("id" integer primary key autoincrement, "at" text not null, "user_id" text, "action" text not null, "target" text, "detail" text default '{}' not null, "ip" text);
CREATE TABLE IF NOT EXISTS "oauth_clients" ("id" text primary key, "name" text not null, "redirect_uris" text not null, "created_at" text not null, "ip" text default '' not null);
CREATE TABLE IF NOT EXISTS "agent_connections" ("id" text primary key, "user_id" text not null references "users" ("id"), "client_id" text not null references "oauth_clients" ("id") on delete cascade, "access_hash" text, "access_expires_at" text, "refresh_hash" text, "previous_refresh_hash" text, "created_at" text not null, "last_used_at" text not null, "expires_at" text not null, "revoked_at" text, "revoked_by" text, "ip" text default '' not null, "user_agent" text default '' not null);
CREATE TABLE IF NOT EXISTS "content_changes" ("id" integer primary key check (id = 1), "n" integer not null);
CREATE TABLE IF NOT EXISTS "calendar_sources" ("id" text primary key, "listing_id" text not null references "pages" ("id"), "name" text not null, "address" text not null, "category" text, "location" text, "enabled" integer default 1 not null, "position" integer not null, "created_at" text not null, "checked_at" text, "synced_at" text, "error" text, "failures" integer default 0 not null, "events" integer default 0 not null, "held_found" integer, "accept_drop" integer default 0 not null);
CREATE TABLE IF NOT EXISTS "calendar_events" ("listing_id" text not null references "pages" ("id"), "key" text not null, "page_id" text not null references "pages" ("id"), "sources" text not null, "hash" text not null, "starts_at" text not null, "live" integer not null, constraint "calendar_events_pk" primary key ("listing_id", "key"));
CREATE TABLE IF NOT EXISTS "api_tokens" ("id" text primary key, "user_id" text not null references "users" ("id"), "token_hash" text not null unique, "hint" text not null, "created_at" text not null, "created_by" text references "users" ("id"), "expires_at" text, "last_used_at" text, "revoked_at" text, "revoked_by" text references "users" ("id"));
CREATE TABLE IF NOT EXISTS "api_token_listings" ("token_id" text not null references "api_tokens" ("id") on delete cascade, "listing_id" text not null references "pages" ("id"), constraint "api_token_listings_pk" primary key ("token_id", "listing_id"));
CREATE TABLE IF NOT EXISTS "api_token_areas" ("token_id" text not null references "api_tokens" ("id") on delete cascade, "area" text not null, constraint "api_token_areas_pk" primary key ("token_id", "area"));
DELETE FROM sqlite_sequence;
CREATE INDEX "revisions_page_id" on "revisions" ("page_id");
CREATE INDEX "jobs_status" on "jobs" ("status", "created_at");
CREATE INDEX "pages_parent_id" on "pages" ("parent_id");
CREATE INDEX "media_usage_owner" on "media_usage" ("owner");
CREATE INDEX "jobs_run_at" on "jobs" ("status", "run_at");
CREATE INDEX "revisions_page_created" on "revisions" ("page_id", "created_at");
CREATE INDEX "pages_listing_publish_at" on "pages" ("parent_id", "kind", "publish_at");
CREATE INDEX "sessions_user" on "sessions" ("user_id");
CREATE INDEX "audit_log_at" on "audit_log" ("at");
CREATE INDEX "audit_log_user" on "audit_log" ("user_id", "id");
CREATE INDEX "audit_log_action" on "audit_log" ("action", "id");
CREATE UNIQUE INDEX pages_sibling_slug on pages (coalesce(parent_id, ''), slug)
        where deleted_at is null;
CREATE UNIQUE INDEX "agent_connections_access" on "agent_connections" ("access_hash");
CREATE UNIQUE INDEX "agent_connections_refresh" on "agent_connections" ("refresh_hash");
CREATE UNIQUE INDEX "agent_connections_previous" on "agent_connections" ("previous_refresh_hash");
CREATE INDEX "agent_connections_user" on "agent_connections" ("user_id", "created_at");
CREATE INDEX "agent_connections_client" on "agent_connections" ("client_id");
CREATE INDEX "audit_log_action_at" on "audit_log" ("action", "at");
CREATE TRIGGER pages_insert_counts AFTER INSERT ON pages BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER pages_update_counts AFTER UPDATE ON pages BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER pages_delete_counts AFTER DELETE ON pages BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER settings_insert_counts AFTER INSERT ON settings BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER settings_update_counts AFTER UPDATE ON settings BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER settings_delete_counts AFTER DELETE ON settings BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER media_insert_counts AFTER INSERT ON media BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER media_update_counts AFTER UPDATE ON media BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER media_delete_counts AFTER DELETE ON media BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER redirects_insert_counts AFTER INSERT ON redirects BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER redirects_update_counts AFTER UPDATE ON redirects BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE TRIGGER redirects_delete_counts AFTER DELETE ON redirects BEGIN UPDATE content_changes SET n = n + 1 WHERE id = 1; END;
CREATE INDEX "calendar_sources_listing" on "calendar_sources" ("listing_id", "position");
COMMIT;
